{
  "PROP-57888860-inv-006": {
    "property_id": "PROP-57888860-inv-006",
    "audit_result": {
      "property_id": "PROP-57888860-inv-006",
      "classification": "vulnerability",
      "code_path": "beacon-chain/core/peerdas/reconstruction.go::ReconstructDataColumnSidecars::L75-86",
      "proof_trace": "Go map iteration order is randomized by language spec. Lines 79-82 build cellsIndices by iterating sidecarByIndex map without sorting, passing unsorted indices to RecoverCellsAndKZGProofs (line 86). The c-kzg-4844 library requires sorted indices (verified by test at fulu__kzg__recover_cells_and_kzg_proofs_test.go:45-57 which expects failure for unsorted input).",
      "attack_scenario": "Attacker sends valid DataColumnSidecars via P2P. Node's reconstruction randomly orders cell indices due to map iteration, causing RecoverCellsAndKZGProofs to fail or produce incorrect recovery results, breaking PeerDAS reconstruction.",
      "checklist_id": "PROP-57888860-inv-006"
    },
    "text": "Recovery cell_indices must be unique and sorted in ascending order.",
    "assertion": "forall recover(cell_indices): is_sorted(cell_indices) AND is_unique(cell_indices)",
    "covers": "SG-024",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

